    Bug 1926711 - Account Hub Font Awareness, manual config inputs should stack at 17px font size. r=aleca

    Differential Revision: https://phabricator.services.mozilla.com/D238528

diff --git a/mail/components/accountcreation/content/widgets/email-manual-incoming-form.mjs b/mail/components/accountcreation/content/widgets/email-manual-incoming-form.mjs
index a015cbe91f7..f15e625c0c2 100644
--- a/mail/components/accountcreation/content/widgets/email-manual-incoming-form.mjs
+++ b/mail/components/accountcreation/content/widgets/email-manual-incoming-form.mjs
@@ -201,6 +201,10 @@ class EmailIncomingForm extends AccountHubStep {
    * @param {AccountConfig} configData - Applies the config data to this state.
    */
   setState(configData) {
+    this.classList.toggle(
+      "stacked",
+      Services.prefs.getIntPref("mail.uifontsize") >= 17
+    );
     this.#currentConfig = configData;
     this.updateFields(this.#currentConfig);
     this.#checkFormValidity();
diff --git a/mail/components/accountcreation/content/widgets/email-manual-outgoing-form.mjs b/mail/components/accountcreation/content/widgets/email-manual-outgoing-form.mjs
index 2a40c5b5892..7661125eeab 100644
--- a/mail/components/accountcreation/content/widgets/email-manual-outgoing-form.mjs
+++ b/mail/components/accountcreation/content/widgets/email-manual-outgoing-form.mjs
@@ -185,6 +185,10 @@ class EmailOutgoingForm extends AccountHubStep {
    * @param {AccountConfig} configData - Applies the config data to this state.
    */
   setState(configData) {
+    this.classList.toggle(
+      "stacked",
+      Services.prefs.getIntPref("mail.uifontsize") >= 17
+    );
     this.#currentConfig = configData;
     this.updateFields(this.#currentConfig);
     this.#currentConfig = this.getConfig();
